--- 设置标题
---@param data any
function UIFightTeamRecommendLineupDialog:SetTitle(data)
    if isNull(data) then
        return
    end

    for i, v in ipairs(data) do
        local type = checkNumber(v.type)
        if isNotNull(CellTitle[type]) then
            v.title = CellTitle[type]()
        end
    end
end

--- 阵容列表
---@param maxNum any
function UIFightTeamRecommendLineupDialog:RefreshLoopListView(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
        self.LoopListView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function UIFightTeamRecommendLineupDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("Cell")
    local LB_cell = GetLuaBehaviour(cell.gameObject, LoopCellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
        -- 第一页的节点播放延迟出现的动画
        if index + 1 <= loopListView.DisplayItemCount then
            CfUtils.PlayDelayShowAnimation(cell, index)
        end
    end
    local data = self.data[index + 1]
    local LT_cell = LB_cell.Env
    ---@type UIFightTeamRecommendLineupNode
    LT_cell:Refresh(data)

    return cell
end

--- 规整数据
---@param data any
function UIFightTeamRecommendLineupDialog:RegularData(data)
    if table.count(data) == 0 then
        return {}
    end
    local result = {}
    for i, v in ipairs(data) do
        local ele = {}
        ele.type = v.type
        ele.videoId = v.videoId
        ele.questId = self.questId
        ele.playerInfo = {
            playerId = v.playerId,
            name = v.name,
            level = v.level,
            avatar = v.avatar,
            avatarFrame = v.avatarFrame,
        }
        ele.team = v.team
        ele.power = v.team[1].combatValue
        table.insert(result, ele)
    end

    -- 排序
    table.sort(result, function(a, b)
        return a.type < b.type
    end)
    return result
end

return UIFightTeamRecommendLineupDialog
